fn is_prime(n: i8) -> bool {
    // By definition, prime numbers are >= 2
    if n < 2 {
        return false;
    }

    // Check divisors from 2 up to n-1
    // Loop invariants:
    // - n >= 2
    // - divisor d in [2, n]
    // - For all j in [2, d-1], n % j != 0 (no divisor found yet)
    // Termination measure: (n - d), which decreases on each loop iteration
    let mut d = 2;

    while d < n {
        if n % d == 0 {
            // Found a divisor; n is not prime
            return false;
        }
        d += 1; // Strictly increases, so (n - d) strictly decreases
    }

    // No divisors found, n is prime by definition
    true
}